package com.bank.inventory;

import java.util.List;

// Simulates the real EC2 API: pages of results + a next-token, and a
// transient throttle on the first attempt of page 2 (to exercise retries).
public class FakeEc2Client {
    private int page2Attempts = 0;

    public InstancePage describeInstances(String token) {
        if (token == null) {
            return new InstancePage(List.of(
                new AwsInstance("i-0a1", "m5.large",  "running", "Production"),
                new AwsInstance("i-0a2", "t3.micro",  "running", "Development")),
                "TOKEN-PAGE-2");
        }
        if ("TOKEN-PAGE-2".equals(token)) {
            page2Attempts++;
            if (page2Attempts == 1) {
                throw new ThrottlingException("Rate exceeded (Throttling)");
            }
            return new InstancePage(List.of(
                new AwsInstance("i-0b1", "m5.xlarge", "running", "Production"),
                new AwsInstance("i-0b2", "m5.large",  "stopped", "Production")),
                null); // last page
        }
        return new InstancePage(List.of(), null);
    }
}
