package com.bank.inventory;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class InstanceInventory {
    private static final Logger log = Logger.getLogger(InstanceInventory.class.getName());
    private final FakeEc2Client ec2;
    private final int maxRetries;

    public InstanceInventory(FakeEc2Client ec2, int maxRetries) {
        this.ec2 = ec2;
        this.maxRetries = maxRetries;
    }

    // Paginate ALL pages, retry transient errors, filter server-side-style by tag.
    public List<AwsInstance> listProduction() {
        List<AwsInstance> found = new ArrayList<>();
        String token = null;
        int pageNum = 0;
        do {
            InstancePage page = fetchWithRetry(token, ++pageNum);
            for (AwsInstance inst : page.getInstances()) {
                // Server-side filter equivalent: only Production + running.
                if ("Production".equals(inst.getEnvironmentTag())
                        && "running".equals(inst.getState())) {
                    found.add(inst);
                    log.info(() -> "Found " + inst.getInstanceId()
                        + " type=" + inst.getType() + " state=" + inst.getState());
                }
            }
            token = page.getNextToken();
        } while (token != null);
        log.info(() -> "Total production running instances: " + found.size());
        return found;
    }

    private InstancePage fetchWithRetry(String token, int pageNum) {
        int attempt = 0;
        long backoffMs = 100;
        while (true) {
            try {
                return ec2.describeInstances(token);
            } catch (ThrottlingException e) {
                attempt++;
                if (attempt > maxRetries) {
                    log.severe(() -> "Page " + pageNum + " failed after " + maxRetries + " retries");
                    throw e;
                }
                long wait = backoffMs;
                log.warning(() -> "Throttled on page " + pageNum + " — retry " + attempt
                    + " after " + wait + "ms");
                sleep(backoffMs);
                backoffMs *= 2; // exponential backoff
            }
        }
    }

    private void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
    }
}
