package com.bank.inventory;

import java.util.logging.*;

public class Ec2InventoryDemo {
    private static final Logger log = Logger.getLogger(Ec2InventoryDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("NBI EC2 inventory — paginate + retry + filter + log (IAM role credentials)");
        InstanceInventory inventory = new InstanceInventory(new FakeEc2Client(), 3);
        var prod = inventory.listProduction();
        log.info(() -> "Returning " + prod.size() + " production instances to caller.");
    }
}
